--
-- Name: fn_match_financial_summary(integer); Type: FUNCTION; Schema: public; Owner: betmaster_user
--

CREATE FUNCTION public.fn_match_financial_summary(p_match_id integer DEFAULT NULL::integer) RETURNS TABLE(summary_match_id integer, home_team character varying, away_team character varying, match_status character varying, final_result character varying, total_bets integer, pending_bets integer, won_bets integer, lost_bets integer, total_stake numeric, potential_liability numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_match_rec RECORD;
    v_multiplier NUMERIC(10,2);
BEGIN
    FOR v_match_rec IN
        SELECT
            m.match_id,
            ht.team_name AS home_team_name,
            at.team_name AS away_team_name,
            m.status,
            m.final_result,
            b.predicted_result,
            b.bet_status,
            b.bet_amount,
            o.home_win_odd,
            o.draw_odd,
            o.away_win_odd
        FROM matches m
        LEFT JOIN teams ht
            ON ht.team_id = m.home_team_id
        LEFT JOIN teams at
            ON at.team_id = m.away_team_id
        LEFT JOIN bets b
            ON b.match_id = m.match_id
        LEFT JOIN odds o
            ON o.match_id = m.match_id
        WHERE p_match_id IS NULL OR m.match_id = p_match_id
        ORDER BY m.match_id
    LOOP
        IF summary_match_id IS DISTINCT FROM v_match_rec.match_id THEN
            IF summary_match_id IS NOT NULL THEN
                RETURN NEXT;
            END IF;

            summary_match_id := v_match_rec.match_id;
            home_team := v_match_rec.home_team_name;
            away_team := v_match_rec.away_team_name;
            match_status := v_match_rec.status;
            final_result := v_match_rec.final_result;
            total_bets := 0;
            pending_bets := 0;
            won_bets := 0;
            lost_bets := 0;
            total_stake := 0;
            potential_liability := 0;
        END IF;

        IF v_match_rec.bet_amount IS NOT NULL THEN
            total_bets := total_bets + 1;
            total_stake := total_stake + v_match_rec.bet_amount;

            IF v_match_rec.bet_status = 'Pending' THEN
                pending_bets := pending_bets + 1;

                v_multiplier := CASE v_match_rec.predicted_result
                    WHEN 'Home' THEN v_match_rec.home_win_odd
                    WHEN 'Draw' THEN v_match_rec.draw_odd
                    WHEN 'Away' THEN v_match_rec.away_win_odd
                    ELSE 1
                END;

                potential_liability := potential_liability + (v_match_rec.bet_amount * COALESCE(v_multiplier, 1));
            ELSIF v_match_rec.bet_status = 'Won' THEN
                won_bets := won_bets + 1;
            ELSIF v_match_rec.bet_status = 'Lost' THEN
                lost_bets := lost_bets + 1;
            END IF;
        END IF;
    END LOOP;

    IF summary_match_id IS NOT NULL THEN
        RETURN NEXT;
    ELSIF p_match_id IS NOT NULL THEN
        RAISE EXCEPTION 'Match % was not found', p_match_id;
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'fn_match_financial_summary failed for match %. Error: %', p_match_id, SQLERRM;
        RAISE;
END;
$$;


ALTER FUNCTION public.fn_match_financial_summary(p_match_id integer) OWNER TO betmaster_user;

--
-- Name: fn_open_user_risk_report(numeric); Type: FUNCTION; Schema: public; Owner: betmaster_user
--

CREATE FUNCTION public.fn_open_user_risk_report(p_min_risk_score numeric DEFAULT 50) RETURNS refcursor
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_user_rec RECORD;
    v_risk_score NUMERIC(10,2);
    v_reason VARCHAR(300);
    v_report_cursor REFCURSOR := 'risk_report_cursor';

    user_activity_cur CURSOR FOR
        SELECT
            u.user_id,
            u.full_name,
            u.balance,
            u.account_status,
            COUNT(b.bet_id) AS total_bets,
            COALESCE(SUM(b.bet_amount), 0) AS total_bet_amount,
            COALESCE(SUM(CASE WHEN b.bet_status = 'Pending' THEN b.bet_amount ELSE 0 END), 0) AS pending_amount,
            COUNT(CASE WHEN b.bet_status = 'Won' THEN 1 END) AS won_bets,
            COUNT(CASE WHEN b.bet_status = 'Lost' THEN 1 END) AS lost_bets,
            COALESCE(SUM(CASE WHEN t.transaction_type = 'Withdrawal' THEN t.amount ELSE 0 END), 0) AS withdrawals
        FROM users u
        LEFT JOIN bets b
            ON b.user_id = u.user_id
        LEFT JOIN transactions t
            ON t.user_id = u.user_id
        GROUP BY u.user_id, u.full_name, u.balance, u.account_status;
BEGIN
    IF p_min_risk_score < 0 THEN
        RAISE EXCEPTION 'Minimum risk score must be non-negative. Received: %', p_min_risk_score;
    END IF;

    OPEN user_activity_cur;

    LOOP
        FETCH user_activity_cur INTO v_user_rec;
        EXIT WHEN NOT FOUND;

        v_risk_score := 0;
        v_reason := '';

        IF v_user_rec.pending_amount > v_user_rec.balance THEN
            v_risk_score := v_risk_score + 45;
            v_reason := v_reason || 'Pending exposure is greater than balance. ';
        END IF;

        IF v_user_rec.lost_bets > v_user_rec.won_bets * 3 AND v_user_rec.total_bets >= 10 THEN
            v_risk_score := v_risk_score + 25;
            v_reason := v_reason || 'Loss ratio is high. ';
        END IF;

        IF v_user_rec.withdrawals > v_user_rec.balance * 2 AND v_user_rec.withdrawals > 0 THEN
            v_risk_score := v_risk_score + 20;
            v_reason := v_reason || 'Withdrawals are high compared with balance. ';
        END IF;

        IF v_user_rec.account_status <> 'Active' THEN
            v_risk_score := v_risk_score + 15;
            v_reason := v_reason || 'Account is not active. ';
        END IF;

        IF v_risk_score >= p_min_risk_score THEN
            SELECT v_user_rec.user_id, v_risk_score, COALESCE(NULLIF(v_reason, ''), 'Risk threshold reached'), 'Open'
            WHERE NOT EXISTS (
                SELECT 1
                FROM risk_review_queue rrq
                WHERE rrq.user_id = v_user_rec.user_id
                  AND rrq.status = 'Open'
                  AND rrq.reason = COALESCE(NULLIF(v_reason, ''), 'Risk threshold reached')
            );
        END IF;
    END LOOP;

    CLOSE user_activity_cur;

    OPEN v_report_cursor FOR
        SELECT
            rrq.review_id,
            rrq.user_id,
            u.full_name,
            rrq.risk_score,
            rrq.reason,
            rrq.status,
            rrq.opened_at
        FROM risk_review_queue rrq
        JOIN users u
            ON u.user_id = rrq.user_id
        WHERE rrq.status = 'Open'
          AND rrq.risk_score >= p_min_risk_score
        ORDER BY rrq.risk_score DESC, rrq.opened_at DESC
        LIMIT 25;

    RETURN v_report_cursor;
EXCEPTION
    WHEN OTHERS THEN
        IF user_activity_cur IS NOT NULL THEN
            CLOSE user_activity_cur;
        END IF;
        RAISE NOTICE 'fn_open_user_risk_report failed: %', SQLERRM;
        RAISE;
END;
$$;


ALTER FUNCTION public.fn_open_user_risk_report(p_min_risk_score numeric) OWNER TO betmaster_user;

--
-- Name: proc_recalculate_user_statuses(numeric, numeric, integer); Type: PROCEDURE; Schema: public; Owner: betmaster_user
--

CREATE PROCEDURE public.proc_recalculate_user_statuses(IN p_high_pending_amount numeric DEFAULT 2000, IN p_low_balance numeric DEFAULT 500, IN p_max_users integer DEFAULT 100)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_user_rec RECORD;
    v_new_status VARCHAR(20);
    v_reason VARCHAR(300);
    v_changed_count INT := 0;

    status_cur CURSOR FOR
        SELECT
            u.user_id,
            u.balance,
            u.account_status,
            COUNT(b.bet_id) AS bet_count,
            COALESCE(SUM(CASE WHEN b.bet_status = 'Pending' THEN b.bet_amount ELSE 0 END), 0) AS pending_amount,
            COUNT(CASE WHEN b.bet_status = 'Lost' THEN 1 END) AS lost_bets,
            COUNT(CASE WHEN b.bet_status = 'Won' THEN 1 END) AS won_bets
        FROM users u
        LEFT JOIN bets b
            ON b.user_id = u.user_id
        GROUP BY u.user_id, u.balance, u.account_status
        ORDER BY COALESCE(SUM(CASE WHEN b.bet_status = 'Pending' THEN b.bet_amount ELSE 0 END), 0) DESC,
                 u.user_id
        LIMIT p_max_users;
BEGIN
    IF p_max_users IS NULL OR p_max_users <= 0 THEN
        RAISE EXCEPTION 'p_max_users must be positive. Received: %', p_max_users;
    END IF;

    OPEN status_cur;

    LOOP
        FETCH status_cur INTO v_user_rec;
        EXIT WHEN NOT FOUND;

        v_new_status := v_user_rec.account_status;
        v_reason := NULL;

        IF v_user_rec.pending_amount >= p_high_pending_amount
           OR (v_user_rec.balance <= p_low_balance AND v_user_rec.lost_bets > v_user_rec.won_bets) THEN
            v_new_status := 'Blocked';
            v_reason := 'High pending exposure or low balance with weak betting result';
        ELSIF v_user_rec.bet_count = 0 THEN
            v_new_status := 'Inactive';
            v_reason := 'No betting activity';
        ELSE
            v_new_status := 'Active';
            v_reason := 'Account passed automatic status review';
        END IF;

        IF v_new_status IS DISTINCT FROM v_user_rec.account_status THEN
            UPDATE users
            SET account_status = v_new_status
            WHERE user_id = v_user_rec.user_id;

            v_changed_count := v_changed_count + 1;

            IF v_new_status = 'Blocked' THEN
                VALUES (v_user_rec.user_id, 90, v_reason, 'Open');
            END IF;
        END IF;
    END LOOP;

    CLOSE status_cur;
    RAISE NOTICE 'proc_recalculate_user_statuses changed % users', v_changed_count;
EXCEPTION
    WHEN OTHERS THEN
        IF status_cur IS NOT NULL THEN
            CLOSE status_cur;
        END IF;
        RAISE NOTICE 'proc_recalculate_user_statuses failed: %', SQLERRM;
        RAISE;
END;
$$;


ALTER PROCEDURE public.proc_recalculate_user_statuses(IN p_high_pending_amount numeric, IN p_low_balance numeric, IN p_max_users integer) OWNER TO betmaster_user;

--
-- Name: proc_settle_match(integer, character varying); Type: PROCEDURE; Schema: public; Owner: betmaster_user
--

CREATE PROCEDURE public.proc_settle_match(IN p_match_id integer, IN p_final_result character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_match_rec RECORD;
    v_winning_bet RECORD;
    v_payout NUMERIC(12,2);
    v_total_paid NUMERIC(12,2) := 0;
    v_winners_count INT := 0;
    v_losers_count INT := 0;
    v_next_transaction_id INT;

    winning_bets_cur CURSOR FOR
        SELECT
            b.bet_id,
            b.user_id,
            b.bet_amount,
            b.predicted_result,
            CASE b.predicted_result
                WHEN 'Home' THEN o.home_win_odd
                WHEN 'Draw' THEN o.draw_odd
                WHEN 'Away' THEN o.away_win_odd
            END AS selected_odd
        FROM bets b
        JOIN odds o
            ON o.match_id = b.match_id
        WHERE b.match_id = p_match_id
          AND b.bet_status = 'Pending'
          AND b.predicted_result = p_final_result
        ORDER BY b.bet_id;
BEGIN
    IF p_final_result NOT IN ('Home', 'Draw', 'Away') THEN
        RAISE EXCEPTION 'Invalid final result %. Expected Home, Draw or Away', p_final_result;
    END IF;

    SELECT *
    INTO v_match_rec
    FROM matches
    WHERE match_id = p_match_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Match % was not found', p_match_id;
    END IF;

    IF v_match_rec.status = 'Finished' AND v_match_rec.final_result IS NOT NULL THEN
        RAISE NOTICE 'Match % is already finished with final_result=%', p_match_id, v_match_rec.final_result;
    END IF;

    SELECT COALESCE(MAX(transaction_id), 0) + 1
    INTO v_next_transaction_id
    FROM transactions;

    UPDATE matches
    SET status = 'Finished',
        final_result = p_final_result
    WHERE match_id = p_match_id;

    OPEN winning_bets_cur;

    LOOP
        FETCH winning_bets_cur INTO v_winning_bet;
        EXIT WHEN NOT FOUND;

        v_payout := ROUND(v_winning_bet.bet_amount * COALESCE(v_winning_bet.selected_odd, 1), 2);

        UPDATE bets
        SET bet_status = 'Won'
        WHERE bet_id = v_winning_bet.bet_id;

        UPDATE users
        SET balance = balance + v_payout
        WHERE user_id = v_winning_bet.user_id;

            transaction_id,
            amount,
            transaction_type,
            transaction_date,
            user_id
        )
        VALUES (
            v_next_transaction_id,
            v_payout,
            'Winnings',
            CURRENT_DATE,
            v_winning_bet.user_id
        );

        v_next_transaction_id := v_next_transaction_id + 1;
        v_total_paid := v_total_paid + v_payout;
        v_winners_count := v_winners_count + 1;
    END LOOP;

    CLOSE winning_bets_cur;

    UPDATE bets
    SET bet_status = 'Lost'
    WHERE match_id = p_match_id
      AND bet_status = 'Pending'
      AND predicted_result <> p_final_result;

    GET DIAGNOSTICS v_losers_count = ROW_COUNT;

        match_id,
        final_result,
        affected_bets,
        paid_winnings,
        details
    )
    VALUES (
        p_match_id,
        p_final_result,
        v_winners_count + v_losers_count,
        v_total_paid,
        'Winners: ' || v_winners_count || ', losers: ' || v_losers_count
    );
EXCEPTION
    WHEN OTHERS THEN
        IF winning_bets_cur IS NOT NULL THEN
            CLOSE winning_bets_cur;
        END IF;
        RAISE NOTICE 'proc_settle_match failed for match %. Error: %', p_match_id, SQLERRM;
        RAISE;
END;
$$;


ALTER PROCEDURE public.proc_settle_match(IN p_match_id integer, IN p_final_result character varying) OWNER TO betmaster_user;

--
-- Name: trg_audit_odds_update(); Type: FUNCTION; Schema: public; Owner: betmaster_user
--

CREATE FUNCTION public.trg_audit_odds_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_max_change NUMERIC(10,2);
BEGIN
    IF NEW.home_win_odd <= 1 OR NEW.draw_odd <= 1 OR NEW.away_win_odd <= 1 THEN
        RAISE EXCEPTION 'Odds must remain greater than 1. odd_id=%', NEW.odd_id;
    END IF;

    v_max_change := GREATEST(
        ABS(COALESCE(NEW.home_win_odd, 0) - COALESCE(OLD.home_win_odd, 0)),
        ABS(COALESCE(NEW.draw_odd, 0) - COALESCE(OLD.draw_odd, 0)),
        ABS(COALESCE(NEW.away_win_odd, 0) - COALESCE(OLD.away_win_odd, 0))
    );

    NEW.update_date := CURRENT_DATE;

        odd_id,
        match_id,
        old_home_win_odd,
        new_home_win_odd,
        old_draw_odd,
        new_draw_odd,
        old_away_win_odd,
        new_away_win_odd,
        change_reason
    )
    VALUES (
        OLD.odd_id,
        OLD.match_id,
        OLD.home_win_odd,
        NEW.home_win_odd,
        OLD.draw_odd,
        NEW.draw_odd,
        OLD.away_win_odd,
        NEW.away_win_odd,
        CASE
            WHEN v_max_change >= 1 THEN 'Large odds movement'
            ELSE 'Regular odds update'
        END
    );

    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'trg_audit_odds_update failed for odd %. Error: %', NEW.odd_id, SQLERRM;
        RAISE;
END;
$$;


ALTER FUNCTION public.trg_audit_odds_update() OWNER TO betmaster_user;

--
-- Name: trg_log_user_account_update(); Type: FUNCTION; Schema: public; Owner: betmaster_user
--

CREATE FUNCTION public.trg_log_user_account_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_reason VARCHAR(200);
BEGIN
    IF NEW.balance IS DISTINCT FROM OLD.balance
       AND NEW.account_status IS DISTINCT FROM OLD.account_status THEN
        v_reason := 'Balance and status changed';
    ELSIF NEW.balance IS DISTINCT FROM OLD.balance THEN
        v_reason := 'Balance changed';
    ELSE
        v_reason := 'Status changed';
    END IF;

        user_id,
        old_balance,
        new_balance,
        balance_delta,
        old_status,
        new_status,
        audit_reason
    )
    VALUES (
        NEW.user_id,
        OLD.balance,
        NEW.balance,
        NEW.balance - OLD.balance,
        OLD.account_status,
        NEW.account_status,
        v_reason
    );

    IF NEW.account_status = 'Blocked'
       AND OLD.account_status IS DISTINCT FROM NEW.account_status THEN
        SELECT NEW.user_id, 85, 'User status changed to Blocked by trigger', 'Open'
        WHERE NOT EXISTS (
            SELECT 1
            FROM risk_review_queue rrq
            WHERE rrq.user_id = NEW.user_id
              AND rrq.status = 'Open'
              AND rrq.reason = 'User status changed to Blocked by trigger'
        );
    END IF;

    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'trg_log_user_account_update failed for user %. Error: %', NEW.user_id, SQLERRM;
        RAISE;
END;
$$;


ALTER FUNCTION public.trg_log_user_account_update() OWNER TO betmaster_user;

