--
-- Name: vw_betmaster_user_activity; Type: VIEW; Schema: public; Owner: betmaster_user
--

CREATE VIEW public.vw_betmaster_user_activity AS
 SELECT u.user_id,
    u.full_name,
    u.email,
    u.account_status,
    u.registration_date,
    u.balance,
    count(DISTINCT b.bet_id) AS total_bets,
    COALESCE(sum(b.bet_amount), (0)::numeric) AS total_bet_amount,
    count(DISTINCT
        CASE
            WHEN ((b.bet_status)::text = 'Won'::text) THEN b.bet_id
            ELSE NULL::integer
        END) AS won_bets,
    count(DISTINCT
        CASE
            WHEN ((b.bet_status)::text = 'Lost'::text) THEN b.bet_id
            ELSE NULL::integer
        END) AS lost_bets,
    count(DISTINCT t.transaction_id) AS total_transactions,
    COALESCE(sum(
        CASE
            WHEN ((t.transaction_type)::text = 'Deposit'::text) THEN t.amount
            ELSE (0)::numeric
        END), (0)::numeric) AS total_deposits,
    COALESCE(sum(
        CASE
            WHEN ((t.transaction_type)::text = 'Withdrawal'::text) THEN t.amount
            ELSE (0)::numeric
        END), (0)::numeric) AS total_withdrawals,
    COALESCE(sum(
        CASE
            WHEN ((t.transaction_type)::text = 'Winnings'::text) THEN t.amount
            ELSE (0)::numeric
        END), (0)::numeric) AS total_winnings
   FROM ((public.users u
     LEFT JOIN public.bets b ON ((b.user_id = u.user_id)))
     LEFT JOIN public.transactions t ON ((t.user_id = u.user_id)))
  GROUP BY u.user_id, u.full_name, u.email, u.account_status, u.registration_date, u.balance;


ALTER VIEW public.vw_betmaster_user_activity OWNER TO betmaster_user;

--
-- Name: vw_football_player_performance; Type: VIEW; Schema: public; Owner: betmaster_user
--

CREATE VIEW public.vw_football_player_performance AS
 SELECT fp.player_id,
    fp.player_name,
    fp."position",
    fp.native_country,
    t.team_name,
    t.country AS team_country,
    fpc.player_type,
    fpc.salary,
    count(DISTINCT fpms.match_id) AS matches_played,
    COALESCE(sum(fpms.goals), (0)::bigint) AS total_goals,
    COALESCE(sum(fpms.assists), (0)::bigint) AS total_assists,
    COALESCE(sum(fpms.yellow_card), (0)::bigint) AS yellow_cards,
    COALESCE(sum(fpms.red_card), (0)::bigint) AS red_cards
   FROM (((public.football_players fp
     LEFT JOIN public.football_player_contracts fpc ON ((fpc.player_id = fp.player_id)))
     LEFT JOIN public.teams t ON ((t.team_id = fpc.team_id)))
     LEFT JOIN public.football_player_match_stats fpms ON ((fpms.player_id = fp.player_id)))
  GROUP BY fp.player_id, fp.player_name, fp."position", fp.native_country, t.team_name, t.country, fpc.player_type, fpc.salary;


ALTER VIEW public.vw_football_player_performance OWNER TO betmaster_user;

--
-- Name: vw_integrated_match_betting_context; Type: VIEW; Schema: public; Owner: betmaster_user
--

CREATE VIEW public.vw_integrated_match_betting_context AS
 SELECT m.match_id,
    m.source_system,
    m.match_date,
    m.status,
    m.competition_stage,
    home.team_name AS home_team,
    away.team_name AS away_team,
    m.final_result,
    count(DISTINCT b.bet_id) AS bet_count,
    COALESCE(sum(b.bet_amount), (0)::numeric) AS total_bet_amount,
    count(DISTINCT
        CASE
            WHEN ((b.bet_status)::text = 'Won'::text) THEN b.bet_id
            ELSE NULL::integer
        END) AS won_bets,
    count(DISTINCT
        CASE
            WHEN ((b.bet_status)::text = 'Lost'::text) THEN b.bet_id
            ELSE NULL::integer
        END) AS lost_bets,
    fs.stadium_name AS match_stadium_name,
    hfs.stadium_name AS home_team_stadium_name,
    fms.attendees
   FROM ((((((public.matches m
     LEFT JOIN public.teams home ON ((home.team_id = m.home_team_id)))
     LEFT JOIN public.teams away ON ((away.team_id = m.away_team_id)))
     LEFT JOIN public.bets b ON ((b.match_id = m.match_id)))
     LEFT JOIN public.football_match_stadiums fms ON ((fms.match_id = m.match_id)))
     LEFT JOIN public.football_stadiums fs ON ((fs.stadium_id = fms.stadium_id)))
     LEFT JOIN public.football_stadiums hfs ON ((hfs.stadium_id = home.home_stadium_id)))
  GROUP BY m.match_id, m.source_system, m.match_date, m.status, m.competition_stage, home.team_name, away.team_name, m.final_result, fs.stadium_name, hfs.stadium_name, fms.attendees;


ALTER VIEW public.vw_integrated_match_betting_context OWNER TO betmaster_user;

