--
-- Name: odds odds_audit_update; Type: TRIGGER; Schema: public; Owner: betmaster_user
--

CREATE TRIGGER odds_audit_update BEFORE UPDATE OF home_win_odd, draw_odd, away_win_odd ON public.odds FOR EACH ROW WHEN (((old.home_win_odd IS DISTINCT FROM new.home_win_odd) OR (old.draw_odd IS DISTINCT FROM new.draw_odd) OR (old.away_win_odd IS DISTINCT FROM new.away_win_odd))) EXECUTE FUNCTION public.trg_audit_odds_update();


--
-- Name: users users_account_audit_update; Type: TRIGGER; Schema: public; Owner: betmaster_user
--

CREATE TRIGGER users_account_audit_update AFTER UPDATE OF balance, account_status ON public.users FOR EACH ROW WHEN (((old.balance IS DISTINCT FROM new.balance) OR ((old.account_status)::text IS DISTINCT FROM (new.account_status)::text))) EXECUTE FUNCTION public.trg_log_user_account_update();


